from gurobipy import Model, GRB, quicksum

def build_and_solve():
    tc_records = [r for r in LEGACY_RECORDS if r['source'] and 'TransportationCost.csv' in r['source']]
    warehouse_ids = []
    store_ids = []
    for r in tc_records:
        wid = r['values']['Unnamed: 0']
        if wid not in warehouse_ids:
            warehouse_ids.append(wid)
        for sid in r['values']:
            if sid.startswith('W') and sid not in store_ids:
                store_ids.append(sid)
    warehouse_ids.sort(key=lambda x: int(x[1:]))
    store_ids.sort(key=lambda x: int(x[1:]))
    c_ij = {}
    for r in tc_records:
        i = r['values']['Unnamed: 0']
        for j in store_ids:
            c_ij[i, j] = float(r['values'][j])
    f_list = [3000, 3200, 3100, 2800, 3500, 2700, 2900, 3050, 3100, 2200, 2890]
    cap_list = [180, 160, 200, 150, 170, 190, 160, 175, 170, 180, 190]
    d_list = [30, 40, 20, 35, 20, 25, 45, 38, 32, 41, 44]
    if not len(warehouse_ids) == len(f_list) == len(cap_list):
        raise ValueError('Mismatch in number of warehouses between LEGACY_RECORDS and parameter lists.')
    if not len(store_ids) == len(d_list):
        raise ValueError('Mismatch in number of stores between LEGACY_RECORDS and parameter lists.')
    f_i = {wid: f_list[k] for k, wid in enumerate(warehouse_ids)}
    cap_i = {wid: cap_list[k] for k, wid in enumerate(warehouse_ids)}
    d_j = {sid: d_list[k] for k, sid in enumerate(store_ids)}
    for i in warehouse_ids:
        for j in store_ids:
            if (i, j) not in c_ij:
                raise ValueError(f'Missing transportation cost for ({i},{j})')
    m = Model()
    m.Params.MIPGap = 0.0001
    y_vars = m.addVars(warehouse_ids, vtype=GRB.BINARY, name='')
    x_vars = m.addVars(warehouse_ids, store_ids, vtype=GRB.CONTINUOUS, lb=0, name='')
    m.setObjective(quicksum((f_i[i] * y_vars[i] for i in warehouse_ids)) + quicksum((c_ij[i, j] * x_vars[i, j] for i in warehouse_ids for j in store_ids)), GRB.MINIMIZE)
    for j in store_ids:
        m.addConstr(quicksum((x_vars[i, j] for i in warehouse_ids)) == d_j[j], name='')
    for i in warehouse_ids:
        m.addConstr(quicksum((x_vars[i, j] for j in store_ids)) <= cap_i[i] * y_vars[i], name='')
    m.optimize()
    if m.Status == GRB.OPTIMAL:
        print(m.ObjVal)
        for v in m.getVars():
            print(v.VarName, v.X)
    else:
        print(m.Status)
    return m
m = build_and_solve()